import sys
input = sys.stdin.read
data = input().split()

index = 0
T = int(data[index])
index += 1

results = []

for _ in range(T):
    N = int(data[index])
    index += 1
    A = list(map(int, data[index:index + N]))
    index += N

    freq = {}
    for num in A:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    B = []
    for num in A:
        if freq[num] == 2:
            B.append(num)
            freq[num] -= 1
        else:
            for key in freq:
                if freq[key] == 1:
                    B.append(key)
                    freq[key] -= 1
                    break

    hamming_distance = sum(1 for a, b in zip(A, B) if a != b)
    results.append(f"{hamming_distance}\n{' '.join(map(str, B))}")

print("\n".join(results))
